// Generated by nocturne/build from nocturne/palette.toml. Edit that file, not this one.
// Thunderbird appearance for Nocturne. Linked into the default profile by
// install, next to chrome/. Only appearance preferences live here;
// accounts, filters and everything else in Thunderbird's settings stay yours.
// Removing a line here does not undo it in the profile: reset it in the
// Config Editor (Settings > General > Config Editor).

// Read chrome/userChrome.css and chrome/userContent.css.
user_pref("toolkit.legacyUserProfileCustomizations.stylesheets", true);

// The built-in dark theme is the base the stylesheets recolour.
user_pref("extensions.activeThemeID", "thunderbird-compact-dark@mozilla.org");

// Ask pages for their dark version: HTML mail that has one shows it.
// 0 = dark, 1 = light, 2 = follow the system.
user_pref("layout.css.prefers-color-scheme.content-override", 0);

// Type: IBM Plex Sans to read, Lilex for code and plain text.
user_pref("font.name.sans-serif.x-western", "IBM Plex Sans");
user_pref("font.name.serif.x-western", "IBM Plex Serif");
user_pref("font.name.monospace.x-western", "Lilex Nerd Font Mono");

// The system's own colours. Parts of Thunderbird (Chat, the calendar's side
// panel, dialogs, the blank view before a page loads) draw with these, which
// otherwise come from the GTK theme: Adwaita's greys and a blue accent.
